SINA_SMART["bacterio1-genetics"] = {"lecture":"bacterio1-genetics","title":"Bacterial genetics","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"bacterio1-genetics:e0","text":"Chromosome: single circular dsDNA, essential genes.","topic":"Chromosome and plasmids","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-genetics:e1","text":"Plasmids: 1-100 kb, autonomous replication, non-essential, resistance/virulence.","topic":"Chromosome and plasmids","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-genetics:e2","text":"Conjugative plasmids carry tra genes; non-conjugative ones are mobilised.","topic":"Chromosome and plasmids","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-genetics:e3","text":"Transposons jump between DNA molecules; integrons capture gene cassettes via integrase.","topic":"Mobile genetic elements","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-genetics:e4","text":"Phenotypic variation: reversible, not inherited; genotypic: mutation or transfer.","topic":"Phenotypic and genotypic variation","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-genetics:e5","text":"Mutations: stable, rare (~10⁻⁹), specific, spontaneous.","topic":"Phenotypic and genotypic variation","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-genetics:e6","text":"Antibiotics select, not induce, resistant mutants → combination therapy.","topic":"Phenotypic and genotypic variation","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-genetics:e7","text":"Transformation: naked DNA, competent cells; Griffith 1928 with pneumococcus.","topic":"Horizontal gene transfer","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-genetics:e8","text":"Transduction: bacteriophage carries DNA.","topic":"Horizontal gene transfer","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-genetics:e9","text":"Conjugation: sex pilus; F+, F−, Hfr; commonest route of resistance spread.","topic":"Horizontal gene transfer","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"14uicqd":"a","10fyvz":"a","393bwc":"a","t7nxj5":"a","1y3fktt":"a","1lm36s0":"a","dilwy6":"a","eln4za":"a","1lj9qzz":"a","6bggku":"a","y4hfy0":"a","x0s6nv":"a","1y3s8yq":"a","1fn26w8":"a","1g0wipp":"x"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"bacterio1-genetics:e0":{"s":0,"u":["Chromosome: single circular dsDNA, essential genes.","The bacterial chromosome is a single, long, circular double-stranded DNA (1.5 to over 10 Mb depending on species), in the nucleoid attached to the membrane.","Plasmids are small (1-100 kb), stable, extrachromosomal dsDNA with independent replication , not essential for growth but carrying useful genes: resistance, metabolic, virulence, bacteriocin and pollutant-resistance plasmids."],"dp":[]},"bacterio1-genetics:e1":{"s":0,"u":["Plasmids: 1-100 kb, autonomous replication, non-essential, resistance/virulence.","Plasmids are small (1-100 kb), stable, extrachromosomal dsDNA with independent replication , not essential for growth but carrying useful genes: resistance, metabolic, virulence, bacteriocin and pollutant-resistance plasmids.","Conjugative plasmids carry tra genes and transfer themselves (e.g. the F plasmid of E. coli ); non-conjugative plasmids can be mobilised with the help of a conjugative one."],"dp":[]},"bacterio1-genetics:e2":{"s":0,"u":["Conjugative plasmids carry tra genes; non-conjugative ones are mobilised.","Conjugative plasmids carry tra genes and transfer themselves (e.g. the F plasmid of E. coli ); non-conjugative plasmids can be mobilised with the help of a conjugative one."],"dp":[{"h":"How a hospital outbreak of resistance can cross species","t":"A carbapenemase gene on a conjugative plasmid does not stay with the Klebsiella that first carried it. In a patient's gut, the plasmid can pass by conjugation to E. coli , Enterobacter and other species, and a transposon or integron cassette can hop onto a different plasmid. Infection control teams therefore track the gene and plasmid , not just the species, and screening, isolation and restricting broad-spectrum antibiotics (which select the carriers) are the main defences. Source: the lecture's mobile elements and conjugation."}]},"bacterio1-genetics:e3":{"s":1,"u":["Transposons jump between DNA molecules; integrons capture gene cassettes via integrase.","Integrons are bacterial systems that capture, express and disseminate genes in the form of cassettes , using an integrase; they sit on chromosomes, plasmids or transposons.","Cassettes are inserted or excised by the integrase and, unlike transposons, do not code for the enzyme that moves them; many carry antibiotic resistance."],"dp":[]},"bacterio1-genetics:e4":{"s":2,"u":["Phenotypic variation: reversible, not inherited; genotypic: mutation or transfer.","Genotypic variation changes the genetic material by mutation or gene transfer , and is inherited.","Phenotypic variation changes gene expression (regulation) in response to the environment: induced, reversible , not inherited, no change in the genome."],"dp":[]},"bacterio1-genetics:e5":{"s":2,"u":["Mutations: stable, rare (~10⁻⁹), specific, spontaneous.","A mutation is a sudden, spontaneous or induced, inherited change in a nucleotide sequence."],"dp":[]},"bacterio1-genetics:e6":{"s":2,"u":["Antibiotics select, not induce, resistant mutants → combination therapy.","Antibiotics do not induce resistance mutations: they select pre-existing resistant mutants, which then take over the population."],"dp":[]},"bacterio1-genetics:e7":{"s":3,"u":["Transformation: naked DNA, competent cells; Griffith 1928 with pneumococcus.","Transformation : uptake of naked DNA by competent bacteria ( S. pneumoniae , Neisseria , H. influenzae ).","F+ cells carry the fertility plasmid, F− do not, and Hfr cells have integrated it into their chromosome."],"dp":[]},"bacterio1-genetics:e8":{"s":3,"u":["Transduction: bacteriophage carries DNA.","Transduction : a bacteriophage (a virus of bacteria) carries a fragment of donor DNA to a recipient cell; phages are also being tested as therapy."],"dp":[]},"bacterio1-genetics:e9":{"s":3,"u":["Conjugation: sex pilus; F+, F−, Hfr; commonest route of resistance spread.","Conjugation : transfer, usually of a plasmid, through cell-to-cell contact via a sex pilus , the commonest route in nature, within or between species; it spreads resistance and toxin genes ."],"dp":[]}},"meta":{"14uicqd":{"a":"recall","vg":"bacterio1-genetics:e1/recall/1"},"10fyvz":{"a":"recall","vg":"bacterio1-genetics:e2/recall/1"},"393bwc":{"a":"recall","vg":"bacterio1-genetics:e2/recall/2"},"t7nxj5":{"a":"recall","vg":"bacterio1-genetics:e3/recall/1"},"1y3fktt":{"a":"recall","vg":"bacterio1-genetics:e3/recall/2"},"1lm36s0":{"a":"recall","vg":"bacterio1-genetics:e4/recall/1"},"dilwy6":{"a":"recall","vg":"bacterio1-genetics:e5/recall/1"},"eln4za":{"a":"recall","vg":"bacterio1-genetics:e6/recall/1"},"1lj9qzz":{"a":"recall","vg":"bacterio1-genetics:e5/recall/2"},"6bggku":{"a":"recall","vg":"bacterio1-genetics:e7/recall/1"},"y4hfy0":{"a":"recall","vg":"bacterio1-genetics:e7/recall/2"},"x0s6nv":{"a":"recall","vg":"bacterio1-genetics:e8/recall/1"},"1y3s8yq":{"a":"recall","vg":"bacterio1-genetics:e9/recall/1"},"1fn26w8":{"a":"recall","vg":"bacterio1-genetics:e7/recall/3"}},"explRev":"49456a484864"};
